-- Create "pages" table
CREATE TABLE `pages` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `team_id` varchar(32) NOT NULL, `owner_id` varchar(32) NOT NULL, `kind` enum('html','markdown','svg') NOT NULL, `title` varchar(480) NOT NULL, `sharing` enum('private','members','team') NOT NULL DEFAULT "private", `current_version` bigint NOT NULL, `updated_at` datetime(6) NOT NULL, PRIMARY KEY (`id`), INDEX `page_team_id_owner_id_updated_at` (`team_id`, `owner_id`, `updated_at`), INDEX `page_team_id_sharing_updated_at` (`team_id`, `sharing`, `updated_at`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "page_files" table
CREATE TABLE `page_files` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `version_id` varchar(32) NOT NULL, `team_id` varchar(32) NOT NULL, `path` varchar(255) NOT NULL, `content_type` varchar(100) NOT NULL, `size` bigint NOT NULL, `digest` varchar(32) NOT NULL, PRIMARY KEY (`id`), INDEX `pagefile_team_id_digest` (`team_id`, `digest`), UNIQUE INDEX `pagefile_version_id_path` (`version_id`, `path`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "page_members" table
CREATE TABLE `page_members` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `page_id` varchar(32) NOT NULL, `user_id` varchar(32) NOT NULL, `added_by` varchar(32) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `pagemember_page_id_user_id` (`page_id`, `user_id`), INDEX `pagemember_user_id_page_id` (`user_id`, `page_id`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "page_versions" table
CREATE TABLE `page_versions` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `page_id` varchar(32) NOT NULL, `number` bigint NOT NULL, `author_id` varchar(32) NOT NULL, `host_id` varchar(32) NOT NULL DEFAULT "", `computer` varchar(256) NOT NULL DEFAULT "", `session_id` varchar(128) NOT NULL DEFAULT "", `note` varchar(800) NOT NULL DEFAULT "", `size` bigint NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `pageversion_page_id_number` (`page_id`, `number`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
